import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let empty: List<Int64> = []
    let n = 0
    for x in empty { n = n + 1 }
    io.println("empty ${n}")

    let bs = [true, false, true]
    let t = 0
    for b in bs { if b { t = t + 1 } }
    io.println("bool ${t}")

    let fs = [1.5, 2.25]
    let f = 0.0
    for x in fs { f = f + x }
    io.println("float ${f}")

    let rs = ['a', 'b']
    let r = 0
    for c in rs { r = r + 1 }
    io.println("rune ${r}")

    return Ok(())
}
